  (* [comment removed for export] *)
  Lemma pn_B : forall regs m (s h pix : Z) (v : pixv),
    PIXat m pix v -> p_h v = h -> (1 <= h <= 20000)%Z -> (1 <= p_wpl v <= 20000)%Z -> (4096 <= pix)%Z ->
    rdn SEGS m (Z_to_bv 64 0x1137d0) 8 = Some (Z_to_le_bytes 8 0xfa4b4) ->
    getr regs 10 = Z_to_bv 64 pix -> getr regs 9 = Z_to_bv 64 h ->
    exists regs',
      msteps SEGS (mkst regs (0x6c6e0 : word) m rom) (mkst regs' (0xfa4b4 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 (4 * (p_wpl v * h)) /\ getr regs' 1 = Z_to_bv 64 0x6c704 /\ getr regs' 8 = Z_to_bv 64 pix
      /\ getr regs' 18 = Z_to_bv 64 0x1137d0
      /\ regs_agree (fun r => In r [1; 8; 10; 11; 18]%list) regs regs'.
Proof.
